#include <algorithm>
#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <thread>
#include <vector>

struct Node {
    Node* left;
    Node* right;
};

class Arena {
public:
    explicit Arena(std::uint64_t count)
        : data_(nullptr), used_(0), capacity_(static_cast<std::size_t>(count)) {
        if (capacity_ != 0) {
            data_ = static_cast<Node*>(::operator new(capacity_ * sizeof(Node)));
        }
    }

    ~Arena() {
        ::operator delete(data_);
    }

    Arena(const Arena&) = delete;
    Arena& operator=(const Arena&) = delete;

    inline void reset() {
        used_ = 0;
    }

    inline Node* alloc() {
        return data_ + used_++;
    }

private:
    Node* data_;
    std::size_t used_;
    std::size_t capacity_;
};

static inline std::uint64_t tree_node_count(int depth) {
    return (std::uint64_t(1) << (depth + 1)) - 1;
}

static Node* make_tree(int depth, Arena& arena) {
    Node* node = arena.alloc();

    if (depth > 0) {
        node->left = make_tree(depth - 1, arena);
        node->right = make_tree(depth - 1, arena);
    } else {
        node->left = nullptr;
        node->right = nullptr;
    }

    return node;
}

static std::uint64_t item_check(const Node* node) {
    if (node->left == nullptr) {
        return 1;
    }

    return 1 + item_check(node->left) + item_check(node->right);
}

static std::uint64_t depth_iterations(int n, int depth) {
    return std::uint64_t(1) << (n - depth + 4);
}

static std::uint64_t run_depth(int n, int depth) {
    const std::uint64_t iterations = depth_iterations(n, depth);
    const std::uint64_t nodes_per_tree = tree_node_count(depth);

    unsigned hw = std::thread::hardware_concurrency();
    if (hw == 0) hw = 1;

    const std::size_t bytes_per_tree =
        static_cast<std::size_t>(nodes_per_tree) * sizeof(Node);

    const std::size_t memory_budget = std::size_t(256) * 1024 * 1024;
    unsigned by_memory = 1;
    if (bytes_per_tree != 0) {
        by_memory = static_cast<unsigned>(
            std::max<std::size_t>(1, memory_budget / bytes_per_tree)
        );
    }

    unsigned thread_count = std::min<unsigned>(hw, 16);
    thread_count = std::min<unsigned>(thread_count, by_memory);
    thread_count = std::min<std::uint64_t>(thread_count, iterations);
    if (thread_count == 0) thread_count = 1;

    std::vector<std::thread> threads;
    std::vector<std::uint64_t> partial(thread_count, 0);

    for (unsigned t = 0; t < thread_count; ++t) {
        const std::uint64_t begin = iterations * t / thread_count;
        const std::uint64_t end = iterations * (t + 1) / thread_count;

        threads.emplace_back([&, t, begin, end]() {
            Arena arena(nodes_per_tree);
            std::uint64_t sum = 0;

            for (std::uint64_t i = begin; i < end; ++i) {
                arena.reset();
                Node* tree = make_tree(depth, arena);
                sum += item_check(tree);
            }

            partial[t] = sum;
        });
    }

    for (std::thread& th : threads) {
        th.join();
    }

    std::uint64_t total = 0;
    for (std::uint64_t v : partial) {
        total += v;
    }

    return total;
}

int main(int argc, char** argv) {
    if (argc < 2) {
        return 1;
    }

    const int n = std::atoi(argv[1]);

    const int stretch_depth = n + 1;

    {
        Arena stretch_arena(tree_node_count(stretch_depth));
        Node* stretch_tree = make_tree(stretch_depth, stretch_arena);

        std::cout << "stretch tree of depth " << stretch_depth
                  << "\t check: " << item_check(stretch_tree) << '\n';
    }

    Arena long_lived_arena(tree_node_count(n));
    Node* long_lived_tree = make_tree(n, long_lived_arena);

    for (int depth = 4; depth <= n; depth += 2) {
        const std::uint64_t iterations = depth_iterations(n, depth);
        const std::uint64_t check = run_depth(n, depth);

        std::cout << iterations << "\t trees of depth " << depth
                  << "\t check: " << check << '\n';
    }

    std::cout << "long lived tree of depth " << n
              << "\t check: " << item_check(long_lived_tree) << '\n';

    return 0;
}
