#include <cstdint>
#include <cstdlib>
#include <iostream>
#include <thread>
#include <vector>

static inline void firstPermutation(
    uint64_t idx,
    int n,
    const std::vector<uint64_t>& fact,
    std::vector<unsigned char>& perm,
    std::vector<unsigned char>& tmp,
    std::vector<int>& count
) {
    for (int i = 0; i < n; ++i) perm[i] = static_cast<unsigned char>(i);
    std::fill(count.begin(), count.end(), 0);

    for (int i = n - 1; i > 0; --i) {
        uint64_t d64 = idx / fact[i];
        idx %= fact[i];

        int d = static_cast<int>(d64);
        count[i] = d;

        if (d != 0) {
            int m = i + 1;
            for (int j = 0; j < m; ++j) tmp[j] = perm[j];

            int k = 0;
            for (int j = d; j < m; ++j) perm[k++] = tmp[j];
            for (int j = 0; j < d; ++j) perm[k++] = tmp[j];
        }
    }
}

static inline void nextPermutation(unsigned char* p, int* count) {
    unsigned char first = p[1];
    p[1] = p[0];
    p[0] = first;

    int i = 1;
    while (++count[i] > i) {
        count[i++] = 0;

        unsigned char next = p[0];
        for (int j = 0; j < i; ++j) p[j] = p[j + 1];
        p[i] = next;
    }
}

static inline int flipCount(const unsigned char* perm, unsigned char* tmp, int n) {
    int first = perm[0];
    if (first == 0) return 0;
    if (perm[first] == 0) return 1;

    for (int i = 0; i < n; ++i) tmp[i] = perm[i];

    int flips = 0;
    do {
        int newFirst = tmp[first];
        tmp[first] = static_cast<unsigned char>(first);

        for (int lo = 1, hi = first - 1; lo < hi; ++lo, --hi) {
            unsigned char c = tmp[lo];
            tmp[lo] = tmp[hi];
            tmp[hi] = c;
        }

        first = newFirst;
        ++flips;
    } while (first != 0);

    return flips;
}

struct alignas(64) Result {
    long long checksum = 0;
    int maxFlips = 0;
};

int main(int argc, char** argv) {
    if (argc < 2) return 1;

    int n = std::atoi(argv[1]);

    std::vector<uint64_t> fact(n + 1);
    fact[0] = 1;
    for (int i = 1; i <= n; ++i) fact[i] = fact[i - 1] * static_cast<uint64_t>(i);

    uint64_t total = fact[n];

    unsigned threads = std::thread::hardware_concurrency();
    if (threads == 0) threads = 1;
    if (threads > 64) threads = 64;
    if (total < 100000) threads = 1;
    if (total < threads) threads = static_cast<unsigned>(total);
    if (threads == 0) threads = 1;

    uint64_t desiredChunks = static_cast<uint64_t>(threads) * 32;
    uint64_t chunkSize = (total + desiredChunks - 1) / desiredChunks;
    if (chunkSize == 0) chunkSize = 1;

    uint64_t numChunks = (total + chunkSize - 1) / chunkSize;

    std::atomic<uint64_t> nextChunk(0);
    std::vector<Result> results(threads);
    std::vector<std::thread> pool;
    pool.reserve(threads);

    for (unsigned t = 0; t < threads; ++t) {
        pool.emplace_back([&, t]() {
            std::vector<unsigned char> perm(n), tmp(n);
            std::vector<int> count(n);

            long long checksum = 0;
            int maxFlips = 0;

            for (;;) {
                uint64_t chunk = nextChunk.fetch_add(1, std::memory_order_relaxed);
                if (chunk >= numChunks) break;

                uint64_t start = chunk * chunkSize;
                uint64_t end = std::min(start + chunkSize, total);

                firstPermutation(start, n, fact, perm, tmp, count);

                for (uint64_t idx = start; idx < end; ++idx) {
                    int flips = flipCount(perm.data(), tmp.data(), n);

                    if (idx & 1)
                        checksum -= flips;
                    else
                        checksum += flips;

                    if (flips > maxFlips) maxFlips = flips;

                    if (idx + 1 < end) {
                        nextPermutation(perm.data(), count.data());
                    }
                }
            }

            results[t].checksum = checksum;
            results[t].maxFlips = maxFlips;
        });
    }

    for (auto& th : pool) th.join();

    long long checksum = 0;
    int maxFlips = 0;

    for (const auto& r : results) {
        checksum += r.checksum;
        if (r.maxFlips > maxFlips) maxFlips = r.maxFlips;
    }

    std::cout << checksum << '\n';
    std::cout << "Pfannkuchen(" << n << ") = " << maxFlips << '\n';

    return 0;
}
