static constexpr int IM = 139968;
static constexpr int IA = 3877;
static constexpr int IC = 29573;
static constexpr int LINE_LEN = 60;

struct FastOutput {
    static constexpr size_t BUFSIZE = 1 << 20;
    char buf[BUFSIZE];
    size_t pos = 0;

    ~FastOutput() {
        flush();
    }

    void flush() {
        if (pos) {
            std::fwrite(buf, 1, pos, stdout);
            pos = 0;
        }
    }

    void write(const char* s, size_t n) {
        if (n > BUFSIZE) {
            flush();
            std::fwrite(s, 1, n, stdout);
            return;
        }
        if (pos + n > BUFSIZE) flush();
        std::memcpy(buf + pos, s, n);
        pos += n;
    }

    void writeLiteral(const char* s) {
        write(s, std::strlen(s));
    }
};

struct Prob {
    char c;
    double p;
};

static void make_lookup(char lookup[IM], const Prob* probs, int n) {
    double cumulative[32];
    double sum = 0.0;

    for (int i = 0; i < n; ++i) {
        sum += probs[i].p;
        cumulative[i] = sum;
    }

    for (int s = 0; s < IM; ++s) {
        double r = static_cast<double>(s) / static_cast<double>(IM);
        int i = 0;
        while (i < n - 1 && cumulative[i] <= r) ++i;
        lookup[s] = probs[i].c;
    }
}

static void repeat_fasta(FastOutput& out, const char* seq, size_t seq_len, long long count) {
    char line[LINE_LEN + 1];
    size_t idx = 0;

    while (count > 0) {
        int n = static_cast<int>(std::min<long long>(LINE_LEN, count));

        for (int i = 0; i < n; ++i) {
            line[i] = seq[idx++];
            if (idx == seq_len) idx = 0;
        }

        line[n] = '\n';
        out.write(line, static_cast<size_t>(n + 1));
        count -= n;
    }
}

static void random_fasta(FastOutput& out, const char lookup[IM], long long count, int& seed) {
    char line[LINE_LEN + 1];

    while (count > 0) {
        int n = static_cast<int>(std::min<long long>(LINE_LEN, count));

        for (int i = 0; i < n; ++i) {
            seed = (seed * IA + IC) % IM;
            line[i] = lookup[seed];
        }

        line[n] = '\n';
        out.write(line, static_cast<size_t>(n + 1));
        count -= n;
    }
}

