struct Entry {
    string s;
    unsigned long long count;
};

static void print_frequencies(const unsigned long long *counts, int k) {
    static const char bases[4] = {'A', 'C', 'G', 'T'};

    vector<Entry> entries;
    if (k == 1) {
        for (int i = 0; i < 4; ++i) {
            if (counts[i] != 0) {
                entries.push_back({string(1, bases[i]), counts[i]});
            }
        }
    } else {
        for (int i = 0; i < 4; ++i) {
            for (int j = 0; j < 4; ++j) {
                unsigned long long c = counts[i * 4 + j];
                if (c != 0) {
                    string s;
                    s.push_back(bases[i]);
                    s.push_back(bases[j]);
                    entries.push_back({s, c});
                }
            }
        }
    }

    sort(entries.begin(), entries.end(), [](const Entry &a, const Entry &b) {
        if (a.count != b.count) return a.count > b.count;
        return a.s < b.s;
    });

    unsigned long long total = 0;
    for (const auto &e : entries) total += e.count;

    cout.setf(ios::fixed);
    cout << setprecision(3);

    for (const auto &e : entries) {
        double pct = total ? (100.0 * static_cast<double>(e.count) / static_cast<double>(total)) : 0.0;
        cout << e.s << ' ' << pct << '\n';
    }
