#define USE_X86_AVX 1
#include <immintrin.h>
#else
#define USE_X86_AVX 0
#endif

static inline bool mandel_pixel_scalar(double cr, double ci) {
    double zr = cr;
    double zi = ci;

    for (int i = 1; i < 50; ++i) {
        double zr2 = zr * zr;
        double zi2 = zi * zi;
        double nzi = (zr + zr) * zi + ci;
        double nzr = zr2 - zi2 + cr;
        zr = nzr;
        zi = nzi;

        if (zr * zr + zi * zi > 4.0) {
            return false;
        }
    }
    return true;
}

static void compute_row_scalar(int n, int y, const double* crs, unsigned char* row) {
    const double ci = 2.0 * (double)y / (double)n - 1.0;
    const int stride = (n + 7) >> 3;

    for (int b = 0; b < stride; ++b) {
        unsigned char byte = 0;
        int x0 = b << 3;
        int lim = std::min(8, n - x0);

        for (int k = 0; k < lim; ++k) {
            if (mandel_pixel_scalar(crs[x0 + k], ci)) {
                byte |= (unsigned char)(0x80u >> k);
            }
        }

        row[b] = byte;
    }
}

#if USE_X86_AVX
__attribute__((target("avx")))
static void compute_row_avx(int n, int y, const double* crs, unsigned char* row) {
    const double ci_s = 2.0 * (double)y / (double)n - 1.0;
    const __m256d ci = _mm256_set1_pd(ci_s);
    const __m256d four = _mm256_set1_pd(4.0);

    int x = 0;
    int b = 0;

    for (; x + 7 < n; x += 8, ++b) {
        __m256d cr0 = _mm256_loadu_pd(crs + x);
        __m256d cr1 = _mm256_loadu_pd(crs + x + 4);

        __m256d zr0 = cr0;
        __m256d zi0 = ci;
        __m256d zr1 = cr1;
        __m256d zi1 = ci;

        __m256d active0 = _mm256_cmp_pd(cr0, cr0, _CMP_EQ_OQ);
        __m256d active1 = _mm256_cmp_pd(cr1, cr1, _CMP_EQ_OQ);

        for (int i = 1; i < 50; ++i) {
            __m256d zr20 = _mm256_mul_pd(zr0, zr0);
            __m256d zi20 = _mm256_mul_pd(zi0, zi0);
            __m256d nzi0 = _mm256_add_pd(_mm256_mul_pd(_mm256_add_pd(zr0, zr0), zi0), ci);
            __m256d nzr0 = _mm256_add_pd(_mm256_sub_pd(zr20, zi20), cr0);
            zr0 = nzr0;
            zi0 = nzi0;
            __m256d mag0 = _mm256_add_pd(_mm256_mul_pd(zr0, zr0), _mm256_mul_pd(zi0, zi0));
            active0 = _mm256_and_pd(active0, _mm256_cmp_pd(mag0, four, _CMP_LE_OQ));

            __m256d zr21 = _mm256_mul_pd(zr1, zr1);
            __m256d zi21 = _mm256_mul_pd(zi1, zi1);
            __m256d nzi1 = _mm256_add_pd(_mm256_mul_pd(_mm256_add_pd(zr1, zr1), zi1), ci);
            __m256d nzr1 = _mm256_add_pd(_mm256_sub_pd(zr21, zi21), cr1);
            zr1 = nzr1;
            zi1 = nzi1;
            __m256d mag1 = _mm256_add_pd(_mm256_mul_pd(zr1, zr1), _mm256_mul_pd(zi1, zi1));
            active1 = _mm256_and_pd(active1, _mm256_cmp_pd(mag1, four, _CMP_LE_OQ));

            if ((_mm256_movemask_pd(active0) | _mm256_movemask_pd(active1)) == 0) {
                break;
            }
        }

        int m0 = _mm256_movemask_pd(active0);
        int m1 = _mm256_movemask_pd(active1);

        int n0 = ((m0 & 1) << 3) | ((m0 & 2) << 1) | ((m0 & 4) >> 1) | ((m0 & 8) >> 3);
        int n1 = ((m1 & 1) << 3) | ((m1 & 2) << 1) | ((m1 & 4) >> 1) | ((m1 & 8) >> 3);

        row[b] = (unsigned char)((n0 << 4) | n1);
    }

    if (x < n) {
        unsigned char byte = 0;
        int k = 0;
        for (; x < n; ++x, ++k) {
            if (mandel_pixel_scalar(crs[x], ci_s)) {
                byte |= (unsigned char)(0x80u >> k);
            }
        }
        row[b] = byte;
    }
}
#endif

int main(int argc, char** argv) {
    if (argc < 2) {
        return 1;
    }

#ifdef _WIN32
    _setmode(_fileno(stdout), _O_BINARY);
#endif

    int n = std::atoi(argv[1]);
    if (n <= 0) {
        return 1;
    }

    const int stride = (n + 7) >> 3;

    std::vector<double> crs(n);
    const double inv_n = 2.0 / (double)n;
    for (int x = 0; x < n; ++x) {
        crs[x] = inv_n * (double)x - 1.5;
    }

    std::vector<unsigned char> image((size_t)n * (size_t)stride);

    typedef void (*RowFunc)(int, int, const double*, unsigned char*);
    RowFunc compute_row = compute_row_scalar;

#if USE_X86_AVX
    if (__builtin_cpu_supports("avx")) {
        compute_row = compute_row_avx;
    }
#endif

    const int max_y = n / 2;
    std::atomic<int> next_y(0);

    unsigned int threads_count = std::thread::hardware_concurrency();
    if (threads_count == 0) {
        threads_count = 1;
    }
    threads_count = std::min<unsigned int>(threads_count, (unsigned int)(max_y + 1));

    std::vector<std::thread> threads;
    threads.reserve(threads_count);

    for (unsigned int t = 0; t < threads_count; ++t) {
        threads.emplace_back([&]() {
            for (;;) {
                int y = next_y.fetch_add(1, std::memory_order_relaxed);
                if (y > max_y) {
                    break;
                }

                unsigned char* row = image.data() + (size_t)y * (size_t)stride;
                compute_row(n, y, crs.data(), row);

                if (y > 0) {
                    int mirror = n - y;
                    if (mirror != y && mirror < n) {
                        std::memcpy(image.data() + (size_t)mirror * (size_t)stride, row, (size_t)stride);
                    }
                }
            }
        });
    }

    for (std::thread& th : threads) {
        th.join();
    }

    char header[64];
    int header_len = std::snprintf(header, sizeof(header), "P4\n%d %d\n", n, n);
    std::fwrite(header, 1, (size_t)header_len, stdout);
    std::fwrite(image.data(), 1, image.size(), stdout);

    return 0;
}
