static inline void offset_momentum(System& s) {
    double px = 0.0, py = 0.0, pz = 0.0;

    for (int i = 0; i < NBODIES; ++i) {
        px += s.vx[i] * masses[i];
        py += s.vy[i] * masses[i];
        pz += s.vz[i] * masses[i];
    }

    s.vx[0] = -px / SOLAR_MASS;
    s.vy[0] = -py / SOLAR_MASS;
    s.vz[0] = -pz / SOLAR_MASS;
}

template<int I, int J>
static inline void advance_pair(System& s, const double dt) {
    const double dx = s.x[I] - s.x[J];
    const double dy = s.y[I] - s.y[J];
    const double dz = s.z[I] - s.z[J];

    const double distance = std::sqrt(dx * dx + dy * dy + dz * dz);
    const double mag = dt / (distance * distance * distance);

    s.vx[I] -= dx * masses[J] * mag;
    s.vy[I] -= dy * masses[J] * mag;
    s.vz[I] -= dz * masses[J] * mag;

    s.vx[J] += dx * masses[I] * mag;
    s.vy[J] += dy * masses[I] * mag;
    s.vz[J] += dz * masses[I] * mag;
}

static inline void advance(System& s, const double dt) {
    advance_pair<0, 1>(s, dt);
    advance_pair<0, 2>(s, dt);
    advance_pair<0, 3>(s, dt);
    advance_pair<0, 4>(s, dt);
    advance_pair<1, 2>(s, dt);
    advance_pair<1, 3>(s, dt);
    advance_pair<1, 4>(s, dt);
    advance_pair<2, 3>(s, dt);
    advance_pair<2, 4>(s, dt);
    advance_pair<3, 4>(s, dt);

    s.x[0] += dt * s.vx[0];
    s.y[0] += dt * s.vy[0];
    s.z[0] += dt * s.vz[0];

    s.x[1] += dt * s.vx[1];
    s.y[1] += dt * s.vy[1];
    s.z[1] += dt * s.vz[1];

    s.x[2] += dt * s.vx[2];
    s.y[2] += dt * s.vy[2];
    s.z[2] += dt * s.vz[2];

    s.x[3] += dt * s.vx[3];
    s.y[3] += dt * s.vy[3];
    s.z[3] += dt * s.vz[3];

    s.x[4] += dt * s.vx[4];
    s.y[4] += dt * s.vy[4];
    s.z[4] += dt * s.vz[4];
}

static double energy(const System& s) {
    double e = 0.0;

    for (int i = 0; i < NBODIES; ++i) {
        e += 0.5 * masses[i] *
             (s.vx[i] * s.vx[i] + s.vy[i] * s.vy[i] + s.vz[i] * s.vz[i]);

        for (int j = i + 1; j < NBODIES; ++j) {
            const double dx = s.x[i] - s.x[j];
            const double dy = s.y[i] - s.y[j];
            const double dz = s.z[i] - s.z[j];
            const double distance = std::sqrt(dx * dx + dy * dy + dz * dz);

            e -= (masses[i] * masses[j]) / distance;
        }
    }

    return e;
}

int main(int argc, char** argv) {
    const long long n = std::atoll(argv[1]);

    System s;
    initialize(s);
    offset_momentum(s);

    std::printf("%.9f\n", energy(s));

    constexpr double dt = 0.01;
    for (long long i = 0; i < n; ++i) {
        advance(s, dt);
    }

    std::printf("%.9f\n", energy(s));

    return 0;
}
