using boost::multiprecision::cpp_int;

static cpp_int pow10_int(int n) {
    cpp_int v = 1;
    while (n-- > 0) v *= 10;
    return v;
}

static cpp_int arctan_inverse(unsigned int inv_x, const cpp_int& scale) {
    const unsigned int inv_x2 = inv_x * inv_x;

    cpp_int xpower = scale / inv_x;
    cpp_int sum = xpower;

    bool subtract = true;
    unsigned int denom = 3;

    for (;;) {
        xpower /= inv_x2;
        if (xpower == 0) break;

        cpp_int term = xpower / denom;
        if (term == 0) break;

        if (subtract)
            sum -= term;
        else
            sum += term;

        subtract = !subtract;
        denom += 2;
    }

    return sum;
}

int main(int argc, char** argv) {
    int N = std::atoi(argv[1]);

    const int guard_digits = 50;
    cpp_int scale = pow10_int(N + guard_digits);

    cpp_int pi_scaled = 16 * arctan_inverse(5, scale) - 4 * arctan_inverse(239, scale);
    cpp_int digits_int = pi_scaled / pow10_int(guard_digits + 1);

    std::string digits = digits_int.convert_to<std::string>();

    if ((int)digits.size() < N)
        digits.insert(digits.begin(), N - digits.size(), '0');

    std::string out;
    out.reserve(N + (N + 9) / 10 * 16);

    for (int i = 0; i < N; i += 10) {
        int count = std::min(10, N - i);
        out.append(digits, i, count);

        if (count < 10)
            out.append(10 - count, ' ');

        out += "\t:";
        out += std::to_string(i + count);
        out += '\n';
    }

    std::cout << out;
    return 0;
}
