using namespace std;

static string read_all_stdin() {
    string data;
    char buf[1 << 20];
    while (true) {
        size_t n = fread(buf, 1, sizeof(buf), stdin);
        if (n == 0) break;
        data.append(buf, n);
    }
    return data;
}

static inline bool match_alt(const uint8_t b[8], const uint8_t alt[8]) {
    return (b[0] & alt[0]) && (b[1] & alt[1]) &&
           (b[2] & alt[2]) && (b[3] & alt[3]) &&
           (b[4] & alt[4]) && (b[5] & alt[5]) &&
           (b[6] & alt[6]) && (b[7] & alt[7]);
}

static array<size_t, 9> count_variants(const string& s) {
    constexpr uint8_t A = 1;
    constexpr uint8_t C = 2;
    constexpr uint8_t G = 4;
    constexpr uint8_t T = 8;

    constexpr uint8_t AC  = A | C;
    constexpr uint8_t AG  = A | G;
    constexpr uint8_t AT  = A | T;
    constexpr uint8_t CG  = C | G;
    constexpr uint8_t CT  = C | T;
    constexpr uint8_t GT  = G | T;
    constexpr uint8_t ACG = A | C | G;
    constexpr uint8_t ACT = A | C | T;
    constexpr uint8_t AGT = A | G | T;
    constexpr uint8_t CGT = C | G | T;

    static const uint8_t variants[9][2][8] = {
        { {A,G,G,G,T,A,A,A}, {T,T,T,A,C,C,C,T} },
        { {CGT,G,G,G,T,A,A,A}, {T,T,T,A,C,C,C,ACG} },
        { {A,ACT,G,G,T,A,A,A}, {T,T,T,A,C,C,AGT,T} },
        { {A,G,ACT,G,T,A,A,A}, {T,T,T,A,C,AGT,C,T} },
        { {A,G,G,ACT,T,A,A,A}, {T,T,T,A,AGT,C,C,T} },
        { {A,G,G,G,ACG,A,A,A}, {T,T,T,CGT,C,C,C,T} },
        { {A,G,G,G,T,CGT,A,A}, {T,T,ACG,A,C,C,C,T} },
        { {A,G,G,G,T,A,CGT,A}, {T,ACG,T,A,C,C,C,T} },
        { {A,G,G,G,T,A,A,CGT}, {ACG,T,T,A,C,C,C,T} }
    };

    uint8_t cmap[256] = {};
    cmap[(unsigned char)'a'] = A;
    cmap[(unsigned char)'c'] = C;
    cmap[(unsigned char)'g'] = G;
    cmap[(unsigned char)'t'] = T;

    array<size_t, 9> counts{};
    size_t next_allowed[9] = {};

    const size_t n = s.size();
    if (n < 8) return counts;

    const unsigned char* p = reinterpret_cast<const unsigned char*>(s.data());

    for (size_t i = 0; i + 8 <= n; ++i) {
        uint8_t b[8] = {
            cmap[p[i]],     cmap[p[i + 1]],
            cmap[p[i + 2]], cmap[p[i + 3]],
            cmap[p[i + 4]], cmap[p[i + 5]],
            cmap[p[i + 6]], cmap[p[i + 7]]
        };

        if ((b[0] | b[1] | b[2] | b[3] | b[4] | b[5] | b[6] | b[7]) == 0)
            continue;

        for (int v = 0; v < 9; ++v) {
            if (i >= next_allowed[v] &&
                (match_alt(b, variants[v][0]) || match_alt(b, variants[v][1]))) {
                ++counts[v];
                next_allowed[v] = i + 8;
            }
        }
    }

    return counts;
}

static inline size_t match_subst1(const string& s, size_t i) {
    return (i + 4 <= s.size() &&
            s[i] == 't' && s[i + 1] == 'H' && s[i + 2] == 'a' &&
            (s[i + 3] == 'N' || s[i + 3] == 't')) ? 4 : 0;
}

static inline size_t match_subst2(const string& s, size_t i) {
    if (i + 3 > s.size()) return 0;

    char c0 = s[i], c1 = s[i + 1], c2 = s[i + 2];

    if (c0 == 'a' && c1 == 'N' && c2 == 'D') return 3;
    if (c0 == 'c' && c1 == 'a' && c2 == 'N') return 3;
    if (c0 == 'H' && c1 == 'a' && (c2 == 'D' || c2 == 'S')) return 3;
    if (c0 == 'W' && c1 == 'a' && c2 == 'S') return 3;

    return 0;
}

static inline size_t match_subst3(const string& s, size_t i) {
    if (i + 3 <= s.size() &&
        s[i] == 'a' &&
        (s[i + 1] == 'N' || s[i + 1] == 'S' || s[i + 1] == 't')) {
        return 3;
    }

    if (i + 2 <= s.size() && s[i] == 'B' && s[i + 1] == 'Y') {
        return 2;
    }

    return 0;
}

static void replace_simple(const string& in, string& out, int which) {
    out.clear();
    out.reserve(in.size());

    const char* repl = (which == 1) ? "<4>" : (which == 2) ? "<3>" : "<2>";

    for (size_t i = 0; i < in.size();) {
        size_t m = 0;
        if (which == 1) m = match_subst1(in, i);
        else if (which == 2) m = match_subst2(in, i);
        else m = match_subst3(in, i);

        if (m) {
            out.append(repl, 3);
            i += m;
        } else {
            out.push_back(in[i++]);
        }
    }
}

static void replace_tags(const string& in, string& out) {
    out.clear();
    out.reserve(in.size());

    for (size_t i = 0; i < in.size();) {
        if (in[i] == '<') {
            size_t j = in.find('>', i + 1);
            if (j != string::npos) {
                out.push_back('|');
                i = j + 1;
                continue;
            }
        }
        out.push_back(in[i++]);
    }
}

static void replace_pipes(const string& in, string& out) {
    out.clear();
    out.reserve(in.size());

    for (size_t i = 0; i < in.size();) {
        if (in[i] == '|' && i + 1 < in.size() && in[i + 1] != '|') {
            size_t j = in.find('|', i + 2);
            if (j != string::npos) {
                out.push_back('-');
                i = j + 1;
                continue;
            }
        }
        out.push_back(in[i++]);
    }
}

int main(int argc, char** argv) {
    int N = 0;
    if (argc > 1) N = atoi(argv[1]);
    (void)N;

    string data = read_all_stdin();
    const size_t original_length = data.size();

    size_t w = 0;
    for (size_t r = 0; r < data.size();) {
        if (data[r] == '>') {
            size_t nl = data.find('\n', r + 1);
            if (nl != string::npos) {
                r = nl + 1;
            } else {
                while (r < data.size()) {
                    if (data[r] != '\n') data[w++] = data[r];
                    ++r;
                }
            }
        } else if (data[r] == '\n') {
            ++r;
        } else {
            data[w++] = data[r++];
        }
    }
    data.resize(w);

    const size_t stripped_length = data.size();
    array<size_t, 9> counts = count_variants(data);

    string transformed = std::move(data);
    string buffer;

    replace_simple(transformed, buffer, 1);
    transformed.swap(buffer);

    replace_simple(transformed, buffer, 2);
    transformed.swap(buffer);

    replace_simple(transformed, buffer, 3);
    transformed.swap(buffer);

    replace_tags(transformed, buffer);
    transformed.swap(buffer);

    replace_pipes(transformed, buffer);
    transformed.swap(buffer);

    const size_t final_length = transformed.size();

    static const char* names[9] = {
        "agggtaaa|tttaccct",
        "[cgt]gggtaaa|tttaccc[acg]",
        "a[act]ggtaaa|tttacc[agt]t",
        "ag[act]gtaaa|tttac[agt]ct",
        "agg[act]taaa|ttta[agt]cct",
        "aggg[acg]aaa|ttt[cgt]ccct",
        "agggt[cgt]aa|tt[acg]accct",
        "agggta[cgt]a|t[acg]taccct",
        "agggtaa[cgt]|[acg]ttaccct"
    };

    string output;
    output.reserve(512);

    for (int i = 0; i < 9; ++i) {
        output += names[i];
        output += ' ';
        output += to_string(counts[i]);
        output += '\n';
    }

    output += '\n';
    output += to_string(original_length);
    output += '\n';
    output += to_string(stripped_length);
    output += '\n';
    output += to_string(final_length);
    output += '\n';

    fwrite(output.data(), 1, output.size(), stdout);
    return 0;
}
