static unsigned char comp_table[256];

static inline bool is_newline(unsigned char c) {
    return c == '\n' || c == '\r';
}

static void init_comp_table() {
    for (int i = 0; i < 256; ++i) comp_table[i] = static_cast<unsigned char>(i);

    comp_table[(unsigned char)'A'] = 'T';
    comp_table[(unsigned char)'T'] = 'A';
    comp_table[(unsigned char)'U'] = 'A';
    comp_table[(unsigned char)'C'] = 'G';
    comp_table[(unsigned char)'G'] = 'C';
    comp_table[(unsigned char)'R'] = 'Y';
    comp_table[(unsigned char)'Y'] = 'R';
    comp_table[(unsigned char)'K'] = 'M';
    comp_table[(unsigned char)'M'] = 'K';
    comp_table[(unsigned char)'B'] = 'V';
    comp_table[(unsigned char)'V'] = 'B';
    comp_table[(unsigned char)'D'] = 'H';
    comp_table[(unsigned char)'H'] = 'D';
    comp_table[(unsigned char)'S'] = 'S';
    comp_table[(unsigned char)'W'] = 'W';
    comp_table[(unsigned char)'N'] = 'N';

    comp_table[(unsigned char)'a'] = 't';
    comp_table[(unsigned char)'t'] = 'a';
    comp_table[(unsigned char)'u'] = 'a';
    comp_table[(unsigned char)'c'] = 'g';
    comp_table[(unsigned char)'g'] = 'c';
    comp_table[(unsigned char)'r'] = 'y';
    comp_table[(unsigned char)'y'] = 'r';
    comp_table[(unsigned char)'k'] = 'm';
    comp_table[(unsigned char)'m'] = 'k';
    comp_table[(unsigned char)'b'] = 'v';
    comp_table[(unsigned char)'v'] = 'b';
    comp_table[(unsigned char)'d'] = 'h';
    comp_table[(unsigned char)'h'] = 'd';
    comp_table[(unsigned char)'s'] = 's';
    comp_table[(unsigned char)'w'] = 'w';
    comp_table[(unsigned char)'n'] = 'n';
}

static void reverse_complement(std::string& data, size_t begin, size_t end) {
    if (begin >= end) return;

    size_t left = begin;
    size_t right = end - 1;

    while (left < right) {
        while (left < right && is_newline((unsigned char)data[left])) ++left;
        while (left < right && is_newline((unsigned char)data[right])) --right;

        if (left >= right) break;

        unsigned char l = (unsigned char)data[left];
        unsigned char r = (unsigned char)data[right];

        data[left] = (char)comp_table[r];
        data[right] = (char)comp_table[l];

        ++left;
        --right;
    }

    if (left == right && !is_newline((unsigned char)data[left])) {
        data[left] = (char)comp_table[(unsigned char)data[left]];
    }
}

int main(int argc, char** argv) {
    int N = 0;
    if (argc > 1) N = std::atoi(argv[1]);
    (void)N;

    init_comp_table();

    std::string data;
    char buffer[1 << 20];

    while (true) {
        size_t n = std::fread(buffer, 1, sizeof(buffer), stdin);
        if (n == 0) break;
        data.append(buffer, n);
    }

    const size_t len = data.size();
    size_t pos = 0;

    while (pos < len) {
        if (data[pos] != '>') {
            size_t next = data.find('>', pos);
            if (next == std::string::npos) break;
            pos = next;
        }

        size_t header_end = data.find('\n', pos);
        if (header_end == std::string::npos) break;

        size_t seq_begin = header_end + 1;
        size_t next_header = data.find('>', seq_begin);
        size_t seq_end = (next_header == std::string::npos) ? len : next_header;

        reverse_complement(data, seq_begin, seq_end);

        if (next_header == std::string::npos) break;
        pos = next_header;
    }

    if (!data.empty()) {
        std::fwrite(data.data(), 1, data.size(), stdout);
    }

    return 0;
}
