#include <cstdio>
#include <cstdlib>
#include <thread>
#include <vector>

template <typename F>
static inline void parallel_for_rows(int n, int workers, F func) {
    if (workers <= 1 || n <= 1) {
        func(0, n);
        return;
    }

    workers = std::min(workers, n);
    const int chunk = (n + workers - 1) / workers;

    std::vector<std::thread> threads;
    threads.reserve(workers - 1);

    for (int t = 0; t < workers - 1; ++t) {
        const int begin = t * chunk;
        const int end = std::min(n, begin + chunk);
        threads.emplace_back([&, begin, end]() {
            func(begin, end);
        });
    }

    const int begin = (workers - 1) * chunk;
    func(begin, n);

    for (auto &th : threads) th.join();
}

static inline void multiply_A(const std::vector<double> &x,
                              std::vector<double> &y,
                              int n,
                              int workers) {
    parallel_for_rows(n, workers, [&](int begin, int end) {
        for (int i = begin; i < end; ++i) {
            const double ii = static_cast<double>(i);
            double denom = ii * (ii + 1.0) * 0.5 + ii + 1.0;
            double inc = ii + 1.0;
            double sum = 0.0;

            for (int j = 0; j < n; ++j) {
                sum += x[j] / denom;
                denom += inc;
                inc += 1.0;
            }

            y[i] = sum;
        }
    });
}

static inline void multiply_At(const std::vector<double> &x,
                               std::vector<double> &y,
                               int n,
                               int workers) {
    parallel_for_rows(n, workers, [&](int begin, int end) {
        for (int i = begin; i < end; ++i) {
            const double ii = static_cast<double>(i);
            double denom = ii * (ii + 1.0) * 0.5 + 1.0;
            double inc = ii + 2.0;
            double sum = 0.0;

            for (int j = 0; j < n; ++j) {
                sum += x[j] / denom;
                denom += inc;
                inc += 1.0;
            }

            y[i] = sum;
        }
    });
}

static inline void multiply_AtA(const std::vector<double> &x,
                                std::vector<double> &y,
                                std::vector<double> &tmp,
                                int n,
                                int workers) {
    multiply_A(x, tmp, n, workers);
    multiply_At(tmp, y, n, workers);
}

