    unsigned hw = std::thread::hardware_concurrency();
    int workers = hw ? static_cast<int>(hw) : 1;
    if (n < 1000) workers = 1;
    workers = std::min(workers, 32);

    std::vector<double> u(n, 1.0), v(n, 0.0), tmp(n, 0.0);

    for (int i = 0; i < 10; ++i) {
        multiply_AtA(u, v, tmp, n, workers);
        multiply_AtA(v, u, tmp, n, workers);
